type Theme = AnyMap
type CatalogProduct = { id: string; name: string; slug?: string; basePrice: number; images?: { url: string }[] }
type CatalogCollection = { id: string; name: string; slug: string; description?: string | null; imageUrl?: string | null }
type MediaAsset = { id: string; name: string; url: string; alt?: string | null }
type Snapshot = { theme: Theme; templates: Record<string, Section[]> }
type DrawerTab = 'content' | 'design' | 'advanced'
type MediaTarget = { kind: 'logo' | 'favicon' | 'sectionImage' | 'blockImage'; sectionId?: string; blockId?: string }

