function deepClone<T>(value: T): T { return structuredClone(value) }
function id(prefix: string) { return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}` }

function section(type: string): Section {
  const common = { spacing: 84, contentWidth: 1200, animation: 'fade-up' }
  if (type === 'announcement') return { id: id(type), type, enabled: true, settings: { ...common, text: 'Free shipping on orders over $50', link: '', position: 'above', background: 'primary', textColor: '#ffffff', autoplay: false }, blocks: [] }
  if (type === 'hero') return { id: id(type), type, enabled: true, settings: { ...common, eyebrow: 'NEW COLLECTION', heading: 'Make your store impossible to ignore.', text: 'A storefront that feels alive, sells clearly, and stays fully editable from your admin.', buttonLabel: 'Shop now', buttonUrl: '/shop', secondaryLabel: 'Explore collections', secondaryUrl: '/collections', imageUrl: '', desktopImageUrl: '', mobileImageUrl: '', imageAlt: '', imageHeightMode: 'adapt', minHeight: 640, imageFit: 'cover', focalX: 50, focalY: 50, overlay: 0.24, overlayColor: '#000000', overlayStyle: 'bottom-gradient', contentPosition: 'center-left', textAlign: 'left', contentWidth: 620, fullBleed: true, borderRadius: 0 }, blocks: [] }
  if (type === 'slideshow') return { id: id(type), type, enabled: true, settings: { ...common, heading: 'Featured', subheading: '', autoplay: true, speed: 5, imageHeightMode: 'adapt', minHeight: 560 }, blocks: [1, 2].map(n => ({ id: id('slide'), type: 'slide', settings: { heading: `Slide ${n}`, text: 'Add a campaign message and call to action.', buttonLabel: 'Shop now', buttonUrl: '/shop', imageUrl: '', imageAlt: '', overlay: 0.25 } })) }
  if (type === 'image_with_text') return { id: id(type), type, enabled: true, settings: { ...common, eyebrow: 'THE BRAND', heading: 'Tell your story.', text: 'Combine imagery, copy and a strong call to action.', buttonLabel: 'Learn more', buttonUrl: '/about', imageUrl: '', layout: 'image-right', imageFit: 'cover' }, blocks: [] }
  if (type.includes('product')) return { id: id(type), type, enabled: true, settings: { ...common, heading: type === 'featured_product' ? 'Featured product' : type === 'product_recommendations' ? 'You may also like' : 'Featured products', subheading: 'Best sellers, new arrivals or a hand-picked edit.', limit: type === 'featured_product' ? 1 : 8, columns: type === 'featured_product' ? 1 : 4, showViewAll: true }, blocks: [] }
  if (type.includes('collection')) return { id: id(type), type, enabled: true, settings: { ...common, heading: type === 'main_collection_banner' ? 'Collection' : 'Shop by collection', subheading: 'Build a visual path through your catalog.', limit: 4, columns: 4 }, blocks: [] }
  if (type === 'multicolumn') return { id: id(type), type, enabled: true, settings: { ...common, heading: 'Why shop with us?', subheading: '', columns: 3 }, blocks: ['Fast delivery', 'Secure checkout', 'Helpful support'].map(t => ({ id: id('column'), type: 'column', settings: { heading: t, text: 'Add a benefit or feature.', imageUrl: '' } })) }
  if (type === 'testimonials') return { id: id(type), type, enabled: true, settings: { ...common, heading: 'Loved by customers', subheading: 'Real feedback makes the store feel real.', columns: 3 }, blocks: ['Happy customer', 'Returning customer', 'Verified buyer'].map(a => ({ id: id('quote'), type: 'quote', settings: { quote: 'Beautiful products and a premium experience.', author: a, role: 'Verified buyer', rating: 5 } })) }
  if (type === 'logo_list') return { id: id(type), type, enabled: true, settings: { ...common, heading: 'Featured in', columns: 5 }, blocks: ['Partner 1', 'Partner 2', 'Partner 3', 'Partner 4', 'Partner 5'].map(t => ({ id: id('logo'), type: 'logo', settings: { text: t, imageUrl: '', alt: t } })) }
  if (type === 'faq') return { id: id(type), type, enabled: true, settings: { ...common, heading: 'Frequently asked questions' }, blocks: ['What is your return policy?', 'How fast do you ship?', 'How can I contact support?'].map(q => ({ id: id('faq'), type: 'faq', settings: { question: q, answer: 'Add your answer here.' } })) }
  if (type === 'newsletter') return { id: id(type), type, enabled: true, settings: { ...common, heading: 'Stay in the loop', text: 'Get launches, drops and offers in your inbox.', buttonLabel: 'Subscribe', background: 'primary' }, blocks: [] }
  if (type === 'video') return { id: id(type), type, enabled: true, settings: { ...common, heading: 'Watch the story', text: '', imageUrl: '', url: '', minHeight: 460 }, blocks: [] }
  if (type === 'rich_text') return { id: id(type), type, enabled: true, settings: { ...common, eyebrow: 'ABOUT THE STORE', heading: 'Tell people what makes your brand different.', text: 'Use this space for your story, mission or editorial content.' }, blocks: [] }
  if (type === 'footer') return { id: id(type), type, enabled: true, settings: { ...common, showNewsletter: true, columns: 4 }, blocks: [] }
  return { id: id(type), type, enabled: true, settings: common, blocks: [] }
}

function baseTemplates(initialSections: Section[]): Record<string, Section[]> {
  const home = deepClone(initialSections || []).filter(Boolean)
  const fallback = [section('announcement'), section('hero'), section('product_grid'), section('collection_grid'), section('image_with_text'), section('testimonials'), section('newsletter'), section('footer')]
  return {
    'Home page': home.length ? home : fallback,
    'Products': [section('announcement'), section('header'), section('rich_text'), section('product_grid'), section('newsletter'), section('footer')],
    'Product': [section('announcement'), section('header'), section('featured_product'), section('product_recommendations'), section('newsletter'), section('footer')],
    'Collections': [section('announcement'), section('header'), section('collection_grid'), section('newsletter'), section('footer')],
    'Collection': [section('announcement'), section('header'), section('main_collection_banner'), section('main_collection_grid'), section('newsletter'), section('footer')],
    'Cart': [section('announcement'), section('header'), section('rich_text'), section('newsletter'), section('footer')],
    'Pages': [section('announcement'), section('header'), section('hero'), section('rich_text'), section('image_with_text'), section('newsletter'), section('footer')],
    'Blog': [section('announcement'), section('header'), section('hero'), section('collection_grid'), section('rich_text'), section('newsletter'), section('footer')],
  }
}

